#!/bin/bash
# Utange POS Handheld - installs the Odoo module on DOCKER-ENGINE-1 (container BRV_1.0, database utangevillage).
# Safe: backs up the database first; only adds a new module.
set -e
C=BRV_1.0; DBC=BRV_1.0-db; DB=utangevillage; ADDONS=/opt/BRV_1.0/custom-addons
TS=$(date +%Y%m%d_%H%M%S)
echo "== 1/5 backup of $DB"
mkdir -p /root/backups
docker exec $DBC pg_dump -U odoo -Fc $DB > /root/backups/${DB}_before_utange_$TS.dump
ls -lh /root/backups/${DB}_before_utange_$TS.dump
echo "== 2/5 module files -> $ADDONS/utange_pos_connector"
[ -d $ADDONS/utange_pos_connector ] && mv $ADDONS/utange_pos_connector /root/backups/utange_pos_connector_old_$TS
echo '' | base64 -d | tar xz -C $ADDONS
chmod -R a+rX $ADDONS/utange_pos_connector
ls $ADDONS/utange_pos_connector
echo "== 3/5 install / update the module in $DB (1-3 min)"
MODE=-i; docker exec $DBC psql -U odoo -d $DB -Atc "select state from ir_module_module where name='utange_pos_connector'" | grep -q installed && MODE=-u
docker exec $C sh -c 'A=""; [ -n "$HOST" ] && A="$A --db_host=$HOST"; [ -n "$PORT" ] && A="$A --db_port=$PORT"; [ -n "$USER" ] && A="$A --db_user=$USER"; [ -n "$PASSWORD" ] && A="$A --db_password=$PASSWORD"; odoo -c /etc/odoo/odoo.conf $A -d '$DB' '$MODE' utange_pos_connector --stop-after-init --no-http --log-level=warn' 2>&1 | grep -v "^$" | tail -15
docker exec $DBC psql -U odoo -d $DB -Atc "select name, state, latest_version from ir_module_module where name='utange_pos_connector'"
echo "== 4/5 device PIN for the handhelds"
PIN=$(docker exec $DBC psql -U odoo -d $DB -Atc "select value from ir_config_parameter where key='utange_pos.device_pin'")
if [ -z "$PIN" ]; then
  PIN=$(shuf -i 100000-999999 -n 1)
  docker exec $DBC psql -U odoo -d $DB -qc "insert into ir_config_parameter(key,value,create_uid,write_uid,create_date,write_date) values ('utange_pos.device_pin','$PIN',1,1,now(),now())"
fi
echo "   DEVICE PIN: $PIN   (keep it for BRV; it is typed once on each handheld)"
echo "== 5/5 restart Odoo"
docker restart $C >/dev/null
for i in $(seq 1 30); do sleep 3; code=$(curl -s -o /dev/null -w "%{http_code}" http://127.0.0.1:8067/web/login || true); [ "$code" != "000" ] && break; done
echo "   Odoo answers: HTTP $code"
echo "== POS and locations now:"
docker exec $DBC psql -U odoo -d $DB -Atc "select c.id, c.name, c.utange_require_sheet, c.utange_count_at_close, coalesce(l.complete_name,'(store not set)') from pos_config c left join stock_location l on l.id=c.utange_store_location_id where c.active"
echo "DONE"
